#!/usr/bin/env bash
set -euo pipefail

# Generated by dcli-bootc gen — edit modules/*.yaml instead
# Profile: dayos


# === file: System files ===

# Copy files/ tree into image
rsync -rlptD /ctx/files/ /

# === base: Base system packages ===
dnf5 -y copr enable bigjapka/VeraCrypt
dnf5 -y copr enable linuxgamerlife/lgl-vm-curator
dnf5 -y copr enable scottames/ghostty
dnf5 -y copr enable theblackdon/dcli-bootc

dnf install -y \
    cliphist \
    dcli-bootc \
    ecryptfs-utils \
    fuzzel \
    ghostty \
    gparted \
    lgl-vm-curator \
    noctalia \
    proxychains-ng \
    veracrypt

# === hypr: Hyprland packages ===
dnf5 -y copr enable lionheartp/Hyprland

dnf install -y --best --allowerasing \
    hyprland \
    hyprpolkitagent \
    uwsm \
    xdg-desktop-portal-hyprland

# === nix: Nix package manager ===

dnf install -y \
    nix \
    nix-daemon \
    busybox
systemctl enable --force nix-copy
systemctl enable --force nix.mount
systemctl enable --force nix-daemon

# === font: Nerd fonts ===
dnf5 -y copr enable aquacash5/nerd-fonts

dnf install -y \
    0x-proto-nerd-fonts \
    droid-sans-mono-nerd-fonts \
    fira-code-nerd-fonts \
    fira-mono-nerd-fonts \
    jet-brains-mono-nerd-fonts \
    nerd-fonts-symbols-only \
    terminus-nerd-fonts \
    ubuntu-mono-nerd-fonts \
    ubuntu-nerd-fonts \
    ubuntu-sans-nerd-fonts \
    victor-mono-nerd-fonts \
    zed-mono-nerd-fonts

# === sys: System settings ===
systemctl enable --force bootc-fetch-apply-updates.timer
systemctl enable --force podman.socket

# === cleanup ===
dnf clean all && rm -rf /var/cache/dnf/*
